   "title": "财政部下达2026年育儿补贴补助资金999亿元，同比增10.6%，全年约1100亿元",
   "summary": "财政部近期下达2026年育儿补贴补助资金999亿元，较上年增长10.6%，支持各地为符合条件的婴幼儿发放育儿补贴；预计全年各级财政共安排约1100亿元。0-3岁普惠育儿现金补贴每孩每年3600元（每月300元），三岁以下婴幼儿照护个税专项附加扣除每孩每月2000元。",
   "decision": "宝宝“开心”已出生，0-3岁每年3600元育儿补贴+每月2000元个税抵扣直接减轻家庭育儿成本，记得每年主动申领补贴。",
