   "summary": "10月23日国务院常务会议研究统筹人口与经济社会发展，提出加快建设生育友好型社会，完善婚嫁、生育、养育、教育政策。专家呼吁稳定新出生人口规模，并建议逐步延长育儿补贴年限、扩围学前教育免费。",
