   "summary": "内蒙古已建成87家生育友好医院、116家儿童友好医院；2026年政府免费为新生儿开展苯丙酮尿症、先天性甲状腺功能减低症、听力三项筛查，截至7月底累计免费筛查57653例、筛查率97%以上。",
