   "summary": "多地生育配套政策持续落地：育儿现金补贴加码、生育医保报销范围扩大、婚育假期监管从严、普惠托育持续增加、个税扣除长期有效。建议备孕家庭提前查本地产假/育儿假/补贴标准与灵活就业生育参保规则。",
   "decision": "提前登录深圳/户籍地卫健委与医保局公众号核对生育津贴、补贴与托育名额，双职工家庭优先规划普惠托育资源。",
