   "summary": "山西省家庭健康促进模块试点暨家庭健康指导员实操技能培训班在太原开班，80余名骨干参加；培训设看食品标签、测生命体征、管理体重、识别烟草危害、预防老年跌倒5个模块，解决基层指导员入户'不会讲、不会测、不会指导'难题。",
