   "title": "[海外] 韩国8月出生人口同比增13% 创2019年以来新高",
   "summary": "韩国8月出生人口2.37万人同比增13%，1-8月累计19.38万人创2019年来同期最高，同比增14.5%创历史新高；总和生育率回升至0.95。",
