   "summary": "新华社报道，“十五五”开局之年消费提质扩容与有效投资双向发力。《扩大消费“十五五”规划》明确到2030年社零达60万亿元左右，围绕增收稳岗、社保兜底、供给提质、优化环境部署28条任务，养老、托育、文旅、健康等服务消费置于突出位置。",
   "decision": "内需与消费被定为“十五五”主引擎，消费金融与招联主业处于政策顺风，可围绕服务消费场景优化产品。",
