   "title": "李强签署国务院令公布《事业单位登记管理条例》，12月1日起施行",
   "summary": "李强签署国务院令公布《事业单位登记管理条例》，共6章34条，明确事业单位不得偏离公益服务主责主业、不得违规举办企业，自2026年12月1日起施行。",
   "decision": "事业单位改革规范落地，对公共服务与编制内就业预期有稳定作用，间接影响家庭就业规划。",
