   "title": "国务院常务会议部署进一步扩大内需 加力以旧换新",
   "summary": "国常会明确加力支持消费品以旧换新，家电、汽车等补贴延续；中汽协称10月前三周乘用车零售同比涨超一成，新能源渗透率持续攀升。",
   "decision": "促消费政策延续利好消费金融需求侧，招联可关注以旧换新场景的分期消费机会。",
