   "title": "发改委印发《能源保供中长期合同管理办法（试行）》，12月1日起施行",
   "summary": "国家发展改革委印发《能源保供中长期合同管理办法（试行）》，将电煤、电力、天然气保供中长期合同纳入统一制度规范，自2026年12月1日起施行。",
   "decision": "能源保供制度化，利于冬季用能价格稳定，对家庭取暖与企业生产成本均有缓冲。",
