   "title": "我国载人登月后续任务明确：梦舟载人飞船和揽月着陆器将首次飞行",
   "summary": "第七届载人航天学术大会在北京开幕，披露工程后续将按计划完成长征十号运载火箭技术验证飞行、梦舟载人飞船和揽月着陆器首次飞行、嫦娥七号等任务；年初已成功实施梦舟飞船最大动压逃逸飞行试验。",
   "decision": "国家重大航天工程节点明确，提振科技自信与民族凝聚力，与家庭科普教育（带宝宝看航天）正相关。",
