   "title": "中国海警在中国台湾岛以东海域依法开展常态化执法巡查",
   "summary": "中国海警局表示，中国海警虎狮舰编队在中国台湾岛以东海域依法开展常态化执法巡查；10月以来该编队持续加强相关海域管控，保障正常航行和作业秩序，维护包括台湾同胞在内的中国民众合法权益。",
   "decision": "台海方向常态化巡航体现主权主张，属家庭决策弱相关，但需以“中国台湾”规范表述关注台海局势对区域稳定的影响。",
   "source": "国家安全部/中新网",
