   "title": "[海外] 伊朗同意“两天计划”：首日美履约、次日霍尔木兹海峡开放",
   "summary": "伊朗外长阿拉格齐透露伊朗同意一项“两天计划”：第一天美国采取履约措施（解冻资金、解除海上封锁、给予石油出口豁免），第二天霍尔木兹海峡开放、交通恢复；伊朗称已做好外交与防御两手准备。",
   "decision": "霍尔木兹海峡关系全球能源运输，若开放将缓和油价，利好国内通胀与消费景气，值得持续跟踪。",
