   "title": "[海外] 美伊局势紧张：美或于中期选举后恢复对伊打击，最快11月4日",
   "summary": "多方消息称，美国计划在11月3日中期选举后恢复对伊朗打击，海湾盟友被通报准备“短暂但密集”的行动，最快11月4日；特朗普点名提及伊朗镐山地下核设施，称“10分钟搞定”。伊朗最高领袖下令对威胁作“不受地理限制”的回应。",
   "decision": "中东冲突升级将推升油价与避险波动，间接影响国内油价与招联用户的出行/消费成本，需关注输入性通胀。",
   "source": "环球网/网易",
