   "title": "[海外] 日本拟修订“安保三文件”将国防与经济增长挂钩",
   "summary": "日本政府计划年底修订“安保三文件”时把“国防与经济的良性循环”列为重点，由防卫省与经产省共设新法人，加强装备生产能力并推进技术转移，以强化防卫产业推动经济增长。",
   "decision": "日本防卫与产业绑定，东亚安全格局复杂化，需以“中国台湾”等规范表述关注区域军备动向。",
   "source": "国家安全部/环球网",
