   "title": "[海外] 美国务院批准向乌克兰出售500枚“爱国者”导弹，价值21亿美元",
   "summary": "美国国务院声明，已批准向乌克兰出售500枚“爱国者”导弹及相关设备，价值约21亿美元，费用由伙伴与盟友承担，不涉及美国政府资金；乌方将用加拿大、德国、挪威捐款及欧盟贷款支付。",
   "decision": "俄乌冲突持续消耗，欧洲防务开支上升或拖累其经济增长，间接影响外需与全球贸易环境。",
