   "summary": "哥伦比亚国防部宣布对与委内瑞拉接壤的边境城市库库塔实施军事化管制，军方将在关键区域部署装甲车、设立检查站，并在空军支援下开展监管，以打击当地犯罪团伙。",
   "decision": "拉美边境局势动荡属远端风险，与家庭及招联业务无直接关联。",
