   "title": "[海外] 五角大楼要求北约盟国缓和反俄论调",
   "summary": "路透社报道，美国国防部联络立陶宛、拉脱维亚、爱沙尼亚等北约国家，请求其缓和反俄论调；美方认为欧洲部分领导人表态正在损害欧洲大陆安全。",
   "decision": "北约内部立场分化，地缘不确定性延续，对家庭决策无直接影响。",
