   "overseas": true,
   "title": "[海外] 韩国前总统尹锡悦内乱案结案庭审，特检组再求处死刑",
   "summary": "韩国首尔高等法院10月29日就前总统尹锡悦涉嫌发动内乱案举行结案庭审，特别检察组再次请求法庭判处尹锡悦死刑。案件进入最终评议阶段，判决结果牵动韩国政坛。",
