   "title": "陪诊服务首项国家标准实施，明确12项可开展服务",
   "summary": "我国陪诊行业首个国家标准《社会化陪同就医服务 基本要求》11月1日实施，服务提供者限定为“机构”，明确12项可开展服务（领取预约号、代取药、记录医嘱、生活辅助、情感支持等），并划定不应开展的服务边界。",
   "decision": "家庭就医场景（带宝宝或长辈就诊）可借助合规陪诊机构减负，选择有机构资质的服务方更稳妥。",
